#include <stdio.h>
#include <unistd.h>

int main() {
    pid_t pid = fork();
    if (pid) {
        printf("Parent: PID %d, my child is %d\n", getpid(), pid);
        sleep(30);
        printf("Parent done\n");
    } else {
        printf("Child: PID %d, my parent is %d\n", getpid(), getppid());
        sleep(30);
        printf("Child: my parent is now %d\n", getppid());
    }
    return 0;
}
